<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data Portability · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'data-portability',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><nav class="breadcrumbs"><a href="<?=esc(url_for())?>">Atlas</a><span>›</span><strong>Data Portability</strong></nav><header class="page-header"><div><p class="eyebrow">CONTROL YOUR DATA</p><h1>Import, preview, export, and rollback</h1><p>Every structured import is previewed before it changes organization data.</p></div><a class="button primary" href="<?=esc(url_for('organization-export'))?>">Export organization JSON</a></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Preview structured CSV</h2><form method="post" enctype="multipart/form-data" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="preview_data_import"><label>Import type<select name="import_type"><option value="locations">Locations: name</option><option value="departments">Departments: name, location</option><option value="positions">Positions: name, department, category</option><option value="coverage_requirements">Coverage requirements: preview only</option></select></label><label>CSV file<input type="file" name="csv_file" accept=".csv,text/csv"></label><label>Or paste CSV<textarea name="csv_data" rows="8"></textarea></label><button class="button primary">Create validation preview</button></form></article><article class="panel"><h2>Import jobs</h2><?php foreach($dataImportJobs as $job):?><a class="planning-row" href="<?=esc(url_for('data-portability?job_id='.$job['id']))?>"><span><strong>#<?=$job['id']?> · <?=esc($job['import_type'])?></strong><small><?=$job['valid_count']?> valid · <?=$job['invalid_count']?> invalid · <?=esc($job['status'])?></small></span></a><?php endforeach;?></article><article class="panel span-2"><h2>Selected preview</h2><?php foreach($dataImportRows as $row):?><div class="planning-row"><span><strong>Row <?=$row['row_number']?> · <?=esc($row['status'])?></strong><small><?=esc($row['error_message']?:json_encode($row['payload'],JSON_UNESCAPED_SLASHES))?></small></span></div><?php endforeach;?><?php $selectedMeta=null;foreach($dataImportJobs as $job)if((int)$job['id']===$selectedImportJob)$selectedMeta=$job;if($selectedMeta):?><form method="post" class="planning-row"><?=Csrf::field()?><input type="hidden" name="job_id" value="<?=$selectedImportJob?>"><?php if($selectedMeta['status']==='preview'&&!$selectedMeta['invalid_count']):?><button class="button primary" name="action" value="commit_data_import">Commit import</button><?php elseif($selectedMeta['status']==='committed'):?><button class="button secondary" name="action" value="rollback_data_import">Rollback imported records</button><?php endif;?></form><?php endif;?></article></section></main></body></html>
